from PIL import Image,ImageDraw
im=Image.open('first_frame.png').crop((108,62,140,100)).resize((640,760), Image.Resampling.NEAREST)
d=ImageDraw.Draw(im)
for x in range(108,141):
 X=(x-108)*20
 if x%2==0:d.line([(X,0),(X,760)],fill=(0,255,255),width=1)
 if x%4==0:d.text((X+2,2),str(x),fill=(255,255,0))
for y in range(62,101):
 Y=(y-62)*20
 if y%2==0:d.line([(0,Y),(640,Y)],fill=(255,0,255),width=1)
 if y%4==0:d.text((2,Y+2),str(y),fill=(255,255,0))
im.save('.tmp/spoutgrid.png')
